<script setup>import{computed,onMounted,ref}from'vue';import{request}from'../api';const data=ref({sources:[],rules:[],incidents:[]}),msg=ref('');const critical=computed(()=>data.value.incidents.filter(x=>x.severity==='CRITICAL'&&x.status!=='CLOSED').length);async function load(){try{data.value=await request('/api/siem-ops/dashboard?organizationCode=ZH-SH')}catch(e){msg.value=e.message}}async function create(){try{await request('/api/siem-ops/sources',{method:'POST',body:JSON.stringify({organizationCode:'ZH-SH',sourceCode:'SRC-'+Date.now(),name:'终端安全日志',sourceType:'EDR'})});msg.value='日志源已登记，等待安全管理员启用';await load()}catch(e){msg.value=e.message}}onMounted(load)</script>
<template><section class="head"><div><small>SECURITY OPERATIONS CENTER</small><h3>安全检测与响应中心</h3><p>集中检测安全事件，保留调查证据并跟踪遏制、恢复和复盘。</p></div><button @click="create">接入日志源</button></section><p class="msg" v-if="msg">{{msg}}</p><section class="metrics"><article><span>日志数据源</span><b>{{data.sources.length}}</b><small>终端、网络、应用与云</small></article><article><span>启用规则</span><b>{{data.rules.filter(x=>x.status==='ACTIVE').length}}</b><small>按风险阈值匹配</small></article><article><span>关键事件</span><b>{{critical}}</b><small>需立即响应</small></article></section><section class="board"><article><header><h4>安全事件队列</h4><button @click="load">刷新</button></header><div class="row" v-for="x in data.incidents" :key="x.id"><span :class="['sev',x.severity]">{{x.severity.slice(0,1)}}</span><div><b>{{x.incidentNo}}</b><small>{{x.assignee||'待分派'}} · {{x.responseAction||'待响应'}}</small></div><em>{{x.status}}</em></div><p v-if="!data.incidents.length">当前没有专业安全事件。</p></article><article><header><h4>日志源健康</h4><span>事件时间</span></header><div class="row" v-for="x in data.sources" :key="x.id"><span class="source">{{x.sourceType}}</span><div><b>{{x.name}}</b><small>{{x.sourceCode}} · {{x.lastEventAt?.slice(0,16)||'尚未接收'}}</small></div><em>{{x.status}}</em></div></article></section></template>
<style scoped>.head{padding:27px 30px;border-radius:14px;background:#202c3b;color:#fff;display:flex;justify-content:space-between;align-items:end}.head small{color:#93acd0;letter-spacing:1.4px}.head h3{font-size:25px;margin:8px 0}.head p{margin:0;color:#cad5e4}.head button{border:0;border-radius:8px;padding:11px 17px;background:#dfaa52;color:#202b39;font-weight:700}.msg{padding:10px 14px;background:#f1f5fa;border-left:3px solid #4b6f9f}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:16px 0}.metrics article,.board article{background:#fff;border:1px solid #dce2eb;border-radius:12px;padding:18px}.metrics span,.metrics small{display:block;color:#687789}.metrics b{display:block;font-size:28px;margin:8px 0}.board{display:grid;grid-template-columns:1fr 1fr;gap:16px}.board header,.row{display:flex;justify-content:space-between;align-items:center}.board header{padding-bottom:12px;border-bottom:1px solid #e8edf3}.board header button{border:0;background:transparent;color:#426b9d}.row{gap:10px;padding:14px 0;border-bottom:1px solid #edf1f5}.row div{flex:1}.row small{display:block;color:#748091;margin-top:4px}.row em{font-style:normal;font-size:12px;color:#47668a}.sev{width:29px;height:29px;display:grid;place-items:center;border-radius:8px;background:#fae2df;color:#b33c30;font-weight:800}.source{font-size:10px;padding:5px;background:#e7eef7;color:#41658e;border-radius:5px}@media(max-width:800px){.head{align-items:start;flex-direction:column;gap:20px}.metrics,.board{grid-template-columns:1fr}}</style>
